  assert obj['zh']==r['sourceZH'] and obj['py']==r['sourcePinyin'];printed=f['originalTeachingSourceDeclaration'];teaching=checked(printed)
  for k in printed['sourceJSONPointer'].split('/')[1:]:teaching=teaching[int(k)] if isinstance(teaching,list) else teaching[k]
  assert teaching['zh']==r['sourceZH'] and teaching['py']==r['sourcePinyin'];actual_plot=ROOT/f['actualFourReadingPlot']['file'];assert sha(actual_plot)==f['actualFourReadingPlot']['sha256'];models=[]
