 p=OUT/'four-printed-alternatives-independent-decisions.json';p.write_text(json.dumps({'schemaVersion':1,'producer':ref(pathlib.Path(__file__)),'reviewReportSHA256':sha(REPORT),'producerSourceModelIndex':ref(BASE/'current-middle-two-source-model-index-v2.json'),'freshSourceObservations':observations,'decisions':decisions,'automaticApproval':False},ensure_ascii=False,indent=2)+'\n');print(json.dumps(ref(p)))
